+	"regexp"
+	"strings"

 	"github.com/charmbracelet/log"
 	"github.com/containernetworking/plugins/pkg/ns"
 	goOvs "github.com/digitalocean/go-openvswitch/ovs"
 	clabexec "github.com/srl-labs/containerlab/exec"
