 }

 func (m *ovs) GetLinkEndpointType() clablinks.LinkEndpointType {
 	return clablinks.LinkEndpointTypeBridge
 }
+
+// logicalEndpointName is the topology interface name for link. When that name is not a valid
+// Linux interface name, the netdev keeps a random clab-* name and the topology name is an altname.
+func (n *ovs) logicalEndpointName(link netlink.Link) string {
+	if link == nil {
+		return ""
+	}
+
+	name := link.Attrs().Name
+	alts := make(map[string]struct{}, len(link.Attrs().AltNames))
+	for _, alt := range link.Attrs().AltNames {
+		alts[alt] = struct{}{}
+	}
+
+	for _, ep := range n.GetEndpoints() {
+		iface := ep.GetIfaceName()
+		if iface == name {
+			return iface
+		}
+		if _, ok := alts[clabutils.SanitizeInterfaceName(iface)]; ok {
+			return iface
+		}
+	}
+
+	return name
+}
+
+// removeEndpointPorts deletes the ports on this bridge tagged with the topology interface name.
+func (n *ovs) removeEndpointPorts(endpoint string) error {
+	if endpoint == "" || n.Cfg == nil || n.Cfg.ShortName == "" {
+		return nil
+	}
+
+	c := goOvs.New(goOvs.Timeout(ovsTimeoutSeconds))
+
+	names, err := ovsInterfaceNames(
+		"external_ids:" + ovsEndpointExtID + "=" + ovsMapValue(endpoint),
+	)
+	if err != nil {
+		return err
+	}
+
+	onBridge, err := bridgePortSet(c, n.Cfg.ShortName)
+	if err != nil {
+		return err
+	}
+
+	for _, name := range names {
+		if _, ok := onBridge[name]; !ok {
+			continue
+		}
+		if err := c.VSwitch.DeletePort(n.Cfg.ShortName, name); err != nil {
+			return err
+		}
+	}
+
+	return nil
+}
+
+// removeMissingAutoPorts deletes clab-* ports whose netdev is already gone. Deleting the container
+// side of the veth removes the device and leaves the OVS port in place under that random name.
+func (n *ovs) removeMissingAutoPorts() error {
+	if n.Cfg == nil || n.Cfg.ShortName == "" {
+		return nil
+	}
+
+	c := goOvs.New(goOvs.Timeout(ovsTimeoutSeconds))
+	ports, err := c.VSwitch.ListPorts(n.Cfg.ShortName)
+	if err != nil {
+		return err
+	}
+
+	for _, port := range ports {
+		if !clabAutoPort.MatchString(port) {
+			continue
+		}
+		missing, err := ovsInterfaceDeviceMissing(port)
+		if err != nil {
+			return err
+		}
+		if !missing {
+			continue
+		}
+		log.Debugf(
+			"Removing stale OVS port %q from bridge %q",
+			port,
+			n.Cfg.ShortName,
+		)
+		if err := c.VSwitch.DeletePort(n.Cfg.ShortName, port); err != nil {
+			return err
+		}
+	}
+
+	return nil
+}
+
+func bridgePortSet(c *goOvs.Client, bridge string) (map[string]struct{}, error) {
+	ports, err := c.VSwitch.ListPorts(bridge)
+	if err != nil {
+		return nil, err
+	}
+
+	set := make(map[string]struct{}, len(ports))
+	for _, port := range ports {
+		set[port] = struct{}{}
+	}
+
+	return set, nil
+}
+
+func ovsVsctl(args ...string) ([]byte, error) {
+	args = append([]string{fmt.Sprintf("--timeout=%d", ovsTimeoutSeconds)}, args...)
+
+	return exec.Command("ovs-vsctl", args...).CombinedOutput()
+}
+
+func ovsInterfaceNames(condition string) ([]string, error) {
+	out, err := ovsVsctl(
+		"--format=csv",
+		"--no-headings",
+		"--data=bare",
+		"--columns=name",
+		"find",
+		"Interface",
+		condition,
+	)
+	if err != nil {
+		return nil, fmt.Errorf("find OVS interfaces: %w (%s)", err, out)
+	}
+
+	text := strings.TrimSpace(string(out))
+	if text == "" {
+		return nil, nil
+	}
+
+	return strings.Split(text, "\n"), nil
+}
+
+func ovsInterfaceDeviceMissing(iface string) (bool, error) {
+	out, err := ovsVsctl("--data=bare", "get", "Interface", iface, "error")
+	if err != nil {
+		// The port disappeared between ListPorts and this get. Nothing left to delete.
+		if ovsRowMissing(string(out)) {
+			return false, nil
+		}
+		return false, fmt.Errorf("get OVS interface %q error: %w (%s)", iface, err, out)
+	}
+
+	return ovsDeviceMissing(string(out)), nil
+}
+
+// ovsDeviceMissing reports whether an OVS interface error column says the netdev is gone.
+// A live interface returns "[]".
+func ovsDeviceMissing(errorColumn string) bool {
+	errorColumn = strings.TrimSpace(errorColumn)
+
+	return strings.Contains(errorColumn, "could not open network device")
+}
+
+func ovsRowMissing(output string) bool {
+	return strings.Contains(strings.ToLower(output), "no row")
+}
+
+func ovsMapValue(value string) string {
+	if value == "" {
+		return `""`
+	}
+	for _, r := range value {
+		switch {
+		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9':
+		case strings.ContainsRune("-_.:@", r):
+		default:
+			return fmt.Sprintf("%q", value)
+		}
+	}
+
+	return value
+}
diff --git a/nodes/ovs/ovs_test.go b/nodes/ovs/ovs_test.go
new file mode 100644
index 0000000..d66803c
--- /dev/null
+++ b/nodes/ovs/ovs_test.go
@@ -0,0 +1,192 @@
+package ovs
+
+import (
+	"context"
+	"os"
+	"os/exec"
+	"strings"
+	"testing"
+
+	goOvs "github.com/digitalocean/go-openvswitch/ovs"
+	clablinks "github.com/srl-labs/containerlab/links"
+	clabtypes "github.com/srl-labs/containerlab/types"
+	"github.com/vishvananda/netlink"
+)
+
+func TestOVSDeviceMissing(t *testing.T) {
+	t.Parallel()
+
+	if !ovsDeviceMissing(
+		`"could not open network device clab-deadbeef (No such device)"`,
+	) {
+		t.Fatal("expected a missing netdev to be detected")
+	}
+	if ovsDeviceMissing("[]") {
+		t.Fatal("a live interface reports an empty error set")
+	}
+	if !clabAutoPort.MatchString("clab-1f57ad50") {
+		t.Fatal("expected a containerlab auto port name to match")
+	}
+	if clabAutoPort.MatchString("ixr-dut-30-e1-1") {
+		t.Fatal("topology interface names are not auto ports")
+	}
+	if got := ovsMapValue("ixr-dut-30-e1-1"); got != "ixr-dut-30-e1-1" {
+		t.Fatalf("ovsMapValue() = %q", got)
+	}
+	if got := ovsMapValue("has space"); got != `"has space"` {
+		t.Fatalf("ovsMapValue() = %q", got)
+	}
+	if !ovsRowMissing(`ovs-vsctl: no row "clab-deadbeef" in table Interface`) {
+		t.Fatal("expected a missing OVS row to be detected")
+	}
+	if ovsRowMissing("database connection failed") {
+		t.Fatal("a database failure is not a missing row")
+	}
+}
+
+func TestOVSEndpointPortDoesNotAccumulate(t *testing.T) {
+	if os.Geteuid() != 0 {
+		t.Skip("requires root")
+	}
+	if _, err := exec.LookPath("ovs-vsctl"); err != nil {
+		t.Skip("ovs-vsctl not found")
+	}
+
+	// ixr-dut-30-e1-1 is 15 characters, so it is the OVS port name.
+	// ixr-dut-30-e1-10 is 16 and is recorded as a clab-* port instead.
+	for _, endpoint := range []string{"ixr-dut-30-e1-1", "ixr-dut-30-e1-10"} {
+		t.Run(endpoint, func(t *testing.T) {
+			assertReattachKeepsOnePort(t, endpoint)
+		})
+	}
+}
+
+func assertReattachKeepsOnePort(t *testing.T, endpoint string) {
+	t.Helper()
+
+	bridge := "br-ovs-leak"
+	c := goOvs.New()
+	_ = c.VSwitch.DeleteBridge(bridge)
+	if err := c.VSwitch.AddBridge(bridge); err != nil {
+		t.Skipf("ovsdb is not available: %v", err)
+	}
+	t.Cleanup(func() {
+		_ = goOvs.New().VSwitch.DeleteBridge(bridge)
+	})
+
+	n := &ovs{}
+	if err := n.Init(&clabtypes.NodeConfig{ShortName: bridge}); err != nil {
+		t.Fatalf("init: %v", err)
+	}
+	ep := clablinks.NewEndpointBridge(
+		clablinks.NewEndpointGeneric(n, endpoint, nil),
+		false,
+	)
+	if err := n.AddEndpoint(ep); err != nil {
+		t.Fatalf("add endpoint: %v", err)
+	}
+
+	first, peer := addVethPair(t)
+	if err := n.AddLinkToContainer(
+		context.Background(),
+		first,
+		clablinks.SetNameMACAndUpInterface(first, ep),
+	); err != nil {
+		t.Fatalf("add link: %v", err)
+	}
+	if err := netlink.LinkDel(peer); err != nil {
+		t.Fatalf("delete peer: %v", err)
+	}
+	if ports := dataPorts(t, bridge); len(ports) != 1 {
+		t.Fatalf("peer delete left %v, want the stale port", ports)
+	}
+
+	// An untagged port may belong to the operator and is not removed for a topology interface.
+	if out, err := ovsVsctl("--no-wait", "add-port", bridge, "operator-port"); err != nil {
+		t.Fatalf("add operator port: %v (%s)", err, out)
+	}
+	if err := n.DeleteBridgePort("operator-port"); err != nil {
+		t.Fatalf("delete bridge port: %v", err)
+	}
+	if ports := dataPorts(t, bridge); len(ports) != 2 {
+		t.Fatalf("ports after untagged delete = %v, want the operator port kept", ports)
+	}
+	if err := c.VSwitch.DeletePort(bridge, "operator-port"); err != nil {
+		t.Fatalf("delete operator port: %v", err)
+	}
+
+	// A port named after the interface keeps its config across a reattach.
+	isNamedPort := dataPorts(t, bridge)[0] == endpoint
+	if isNamedPort {
+		if out, err := ovsVsctl("set", "Port", endpoint, "tag=100"); err != nil {
+			t.Fatalf("set tag: %v (%s)", err, out)
+		}
+	}
+
+	second, secondPeer := addVethPair(t)
+	t.Cleanup(func() { _ = netlink.LinkDel(secondPeer) })
+	if err := n.AddLinkToContainer(
+		context.Background(),
+		second,
+		clablinks.SetNameMACAndUpInterface(second, ep),
+	); err != nil {
+		t.Fatalf("reattach: %v", err)
+	}
+	if ports := dataPorts(t, bridge); len(ports) != 1 {
+		t.Fatalf("ports after reattach = %v, want 1", ports)
+	}
+	if isNamedPort {
+		out, err := ovsVsctl("get", "Port", endpoint, "tag")
+		if err != nil || strings.TrimSpace(string(out)) != "100" {
+			t.Fatalf("tag after reattach = %q, err = %v, want 100", out, err)
+		}
+	}
+
+	if err := n.Delete(context.Background()); err != nil {
+		t.Fatalf("delete node: %v", err)
+	}
+	if ports := dataPorts(t, bridge); len(ports) != 0 {
+		t.Fatalf("ports after node delete = %v", ports)
+	}
+}
+
+func addVethPair(t *testing.T) (netlink.Link, netlink.Link) {
+	t.Helper()
+
+	name := clablinks.NewEndpointGeneric(nil, "x", nil).GetRandIfaceName()
+	peerName := name + "p"
+	veth := &netlink.Veth{
+		LinkAttrs: netlink.LinkAttrs{Name: name},
+		PeerName:  peerName,
+	}
+	if err := netlink.LinkAdd(veth); err != nil {
+		t.Fatalf("add veth: %v", err)
+	}
+	link, err := netlink.LinkByName(name)
+	if err != nil {
+		t.Fatalf("lookup veth: %v", err)
+	}
+	peer, err := netlink.LinkByName(peerName)
+	if err != nil {
+		t.Fatalf("lookup peer: %v", err)
+	}
+
+	return link, peer
+}
+
+func dataPorts(t *testing.T, bridge string) []string {
+	t.Helper()
+
+	ports, err := goOvs.New().VSwitch.ListPorts(bridge)
+	if err != nil {
+		t.Fatalf("list ports: %v", err)
+	}
+	var data []string
+	for _, port := range ports {
+		if port != bridge {
+			data = append(data, port)
+		}
+	}
+
+	return data
+}

